INSERT INTO `penyakit` (`id_penyakit`, `kode_penyakit`, `nama_penyakit`, `deskripsi`, `solusi`) VALUES
(1, 'P1', 'Cacingan', 'Infeksi cacing pada kucing, seperti cacing gelang atau cacing pita', 'Infeksi cacing pada kucing, seperti cacing gelang atau cacing pita, dapat diatasi dengan pemberian obat cacing secara rutin sesuai anjuran dokter hewan. Pencegahan meliputi menjaga kebersihan lingkungan, memberikan makanan yang higienis, serta rutin memeriksakan kucing ke dokter hewan untuk deteksi dini.'),
(2, 'P2', 'FPV', 'Penyakit virus yang menyerang sistem pencernaan dan imun.', 'FPV adalah penyakit virus yang sangat menular dan berbahaya. Penanganannya fokus pada perawatan suportif, seperti pemberian cairan infus untuk mencegah dehidrasi, antibiotik untuk mencegah infeksi sekunder, serta obat pereda gejala. Vaksinasi adalah langkah pencegahan utama untuk menghindari infeksi ini.'),
(3, 'P3', 'Flu Kucing', 'Infeksi saluran pernapasan atas pada kucing.', 'Flu kucing disebabkan oleh virus atau bakteri yang menyerang saluran pernapasan. Pengobatan meliputi pemberian antibiotik jika infeksi bakteri terdeteksi, obat antiinflamasi untuk meredakan peradangan, serta asupan cairan dan makanan yang cukup. Menjaga kebersihan lingkungan dan menghindari kontak dengan kucing yang sakit dapat membantu mencegah penyebaran.'),
(4, 'P4', 'Radang Gusi', 'Peradangan pada gusi akibat bakteri atau plak.', 'Radang gusi pada kucing sering kali disebabkan oleh plak dan tartar yang menumpuk. Pengobatannya mencakup pembersihan gigi oleh dokter hewan, pemberian obat antiinflamasi, serta antibiotik jika terjadi infeksi. Pencegahan dapat dilakukan dengan rutin menyikat gigi kucing menggunakan pasta gigi khusus hewan.'),
(5, 'P5', 'Konjungtivitis', 'Peradangan pada selaput mata akibat infeksi.', 'Peradangan pada selaput mata ini dapat disebabkan oleh infeksi virus, bakteri, atau iritasi. Pengobatan melibatkan pemberian obat tetes atau salep mata sesuai penyebabnya, serta menjaga kebersihan mata dengan kain lembut yang dibasahi air hangat. Jika terjadi infeksi sekunder, antibiotik akan diresepkan oleh dokter hewan.'),
(6, 'P6', 'Kutuan', 'Infestasi kutu pada kucing yang menyebabkan gatal.', 'Kutu pada kucing dapat diatasi dengan penggunaan obat antiparasit seperti spot-on, shampoo khusus, atau semprotan anti-kutu. Membersihkan tempat tidur dan lingkungan kucing secara rutin juga penting untuk mencegah infestasi ulang. Jika infestasi parah, dokter hewan mungkin meresepkan obat oral atau suntikan.'),
(7, 'P7', 'Ringworm', 'Infeksi jamur yang menyebabkan lesi pada kulit.', 'Infeksi jamur ini ditangani dengan obat antijamur topikal atau oral, tergantung tingkat keparahan. Lingkungan harus sering dibersihkan untuk menghindari penyebaran spora jamur. Jika ada beberapa kucing di rumah, isolasi kucing yang terinfeksi sangat disarankan untuk mencegah penularan.'),
(8, 'P8', 'Scabies', 'Penyakit kulit akibat tungau yang menyebabkan gatal.', 'Scabies pada kucing disebabkan oleh tungau yang menggali ke dalam kulit, menyebabkan rasa gatal yang sangat parah, kulit menebal, dan munculnya kerak atau koreng terutama di area wajah, telinga, dan kaki. Penanganannya melibatkan pemberian obat antiparasit seperti spot-on, suntikan, atau obat oral yang diresepkan oleh dokter hewan. Selain itu, lingkungan dan perlengkapan kucing seperti tempat tidur dan kandang perlu dibersihkan secara rutin untuk mencegah penyebaran tungau.'),
(9, 'P9', 'Otitis', 'Infeksi telinga yang menyebabkan keluarnya cairan bau.', 'Radang telinga pada kucing bisa disebabkan oleh infeksi bakteri, jamur, atau parasit. Pengobatan tergantung pada penyebabnya dan bisa meliputi pembersihan telinga secara rutin, pemberian obat tetes antibiotik atau antijamur, serta obat antiinflamasi untuk mengurangi rasa sakit.'),
(10, 'P10', 'FULTD', 'Gangguan saluran kemih bagian bawah pada kucing.', 'Penyakit ini mencakup berbagai gangguan saluran kemih, seperti infeksi, batu kandung kemih, atau sumbatan uretra. Penanganannya tergantung penyebabnya, bisa berupa diet khusus, pemberian obat antiinflamasi, antibiotik, atau prosedur medis untuk menghilangkan sumbatan. Pencegahan meliputi pemberian makanan berkualitas dan memastikan kucing cukup minum untuk menjaga kesehatan saluran kemih.');
